/* yuexin_cat_angry.c - YuexinCat 生气 149 帧资源 (64x64, 30 fps, 乒乓循环).
 *
 * 帧数据来源: 用户上传的参考播放器 (149 帧 30 fps MP4 拆帧), 已重打包成
 * 本工程的 XOR 增量格式; V24 起增量位流用静态算术编码压缩, 每帧一个
 * 独立码块 (offsets[] 为字节偏移), 解码器见 animation.c 的 ArBit()。
 * counts[] 为 uint16_t (64x64 帧可改动超过 255 字节)。
 * 体积: frame0 512 + offsets 300 + counts 298 + stream + 概率表(在
 *       yuexin_cat_frames.c 中, 三份动画共享)。
 * 已逐帧往返校验, 与旧格式解码结果逐位相同。由 tools/gen_ycat.py 生成。
 */
